    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('get_weather', {location: 42});

    expect(response.result).toMatch(/location.*string/i);
  });
